let _hasPrewarmedGraphics=!1;
function prewarmGraphics(){
  if(_hasPrewarmedGraphics)return;
  _hasPrewarmedGraphics=!0;
  try{
    const oc=document.createElement("canvas");
    oc.width=128;oc.height=128;
    const ctx=oc.getContext("2d",{willReadFrequently:!1});
    if(!ctx)return;
    const fc=[
      "400 16px 'Cinzel Decorative', serif",
      "400 24px 'Cinzel Decorative', serif",
      "400 32px 'Cinzel Decorative', serif",
      "700 24px 'Cinzel Decorative', serif",
      "700 26px 'Cinzel Decorative', serif",
      "900 48px 'Cinzel Decorative', serif",
      "900 64px 'Cinzel Decorative', serif",
      "700 14px 'Cinzel', serif",
      "700 16px 'Cinzel', serif",
      "700 18px 'Cinzel', serif",
      "400 12px 'Outfit', sans-serif",
      "700 11px 'Outfit', sans-serif",
      "700 14px 'Outfit', sans-serif",
      "700 16px 'Orbitron', sans-serif",
      "400 28px sans-serif"
    ];
    const ts=[
      "WAVE 1234567890 BOSS ALERT WARNING DEFEATED LEVEL UP! MAX ★",
      "0123456789 :,.★/%-+→ DPS RANK NEW RECORD",
      "PLASMA BOLTS PHOTON SUPERCHARGE PLASMA FIELD LASER BEAM SHIELD MATRIX"
    ];
    for(let f=0;f<fc.length;f++){
      ctx.font=fc[f];
      for(let t=0;t<ts.length;t++){
        ctx.fillText(ts[t],0,20);
        ctx.strokeText(ts[t],0,20);
      }
    }
    ctx.shadowBlur=12;ctx.shadowColor="#00ffaa";ctx.fillStyle="#00ffaa";
    ctx.beginPath();ctx.arc(64,64,20,0,Math.PI*2);ctx.fill();
    const rg=ctx.createRadialGradient(64,64,0,64,64,60);
    rg.addColorStop(0,"rgba(0, 255, 221, 0.8)");rg.addColorStop(.5,"rgba(0, 170, 255, 0.4)");rg.addColorStop(1,"rgba(0, 0, 0, 0)");
    ctx.fillStyle=rg;ctx.fillRect(0,0,128,128);
    const lg=ctx.createLinearGradient(0,0,128,0);
    lg.addColorStop(0,"#ff0033");lg.addColorStop(.5,"#ffcc00");lg.addColorStop(1,"#00ff88");
    ctx.fillStyle=lg;ctx.fillRect(0,0,128,128);
    ctx.globalCompositeOperation="lighter";ctx.fillStyle="rgba(255, 255, 255, 0.5)";
    ctx.beginPath();ctx.arc(64,64,30,0,Math.PI*2);ctx.fill();
    ctx.globalCompositeOperation="source-over";
    ctx.lineWidth=3;ctx.strokeStyle="#00e5ff";
    ctx.beginPath();ctx.moveTo(10,10);ctx.quadraticCurveTo(64,120,118,10);ctx.stroke();
    oc.width=1;oc.height=1;
  }catch(e){}
}
if(document.fonts&&document.fonts.ready){
  document.fonts.ready.then(()=>{prewarmGraphics();}).catch(()=>{prewarmGraphics();});
}else{
  setTimeout(prewarmGraphics,150);
}
